-- Insert Quiz Questions for Lesson: Respond Professionally and Fairly

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 15 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 15 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'respond-professionally-fairly' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson respond-professionally-fairly not found in module 15';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What should never be placed in a public response?', 
    '["A thank-you message","Private client, account, health, payment, or case details","The business name","An invitation to contact directly"]'::jsonb,
    'Private client, account, health, payment, or case details',
    'Never place private client, account, health, payment, or case details in a public response. Move sensitive discussions to a private channel.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What should a business request: an honest review or a five-star review?', 
    '["A five-star review","An honest review","Only positive reviews","Reviews with photos"]'::jsonb,
    'An honest review',
    'Businesses should request honest reviews, not guaranteed positive ratings. Asking for five-star reviews violates fair-review practices and platform rules.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What is the first public-response goal when a review is negative?', 
    '["Argue with the reviewer publicly","Acknowledge the concern calmly and invite the right next step","Delete the review immediately","Offer a refund in the public response"]'::jsonb,
    'Acknowledge the concern calmly and invite the right next step',
    'When responding to a negative review, acknowledge the concern calmly and invite the customer to take the next step privately, such as contacting you directly.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;
