-- Insert Quiz Questions for Lesson: Display Reviews and Plan Automation

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 15 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 15 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'display-reviews-plan-automation' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson display-reviews-plan-automation not found in module 15';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Where are review widgets created?', 
    '["Settings → Review Link","Reputation → Widgets","Automation → Workflows","Reputation → Requests"]'::jsonb,
    'Reputation → Widgets',
    'Review widgets are created in Reputation → Widgets, where you can choose layouts, select sources, and customize display settings.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Name one suitable workflow trigger for a service business.', 
    '["A completed appointment, job, or opportunity stage","A new contact being added","A calendar event starting","A payment being refunded"]'::jsonb,
    'A completed appointment, job, or opportunity stage',
    'A completed appointment, job, or opportunity stage (like ''Service Complete'') is a suitable trigger for sending review requests in a service business.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
